class MessageRoutingConflict(ValueError):
    """The client view of a member or running round is stale."""


class ProjectInvocationStoreError(ValueError):
    """A project invocation cannot be replayed or persisted safely."""

    def __init__(self, message: str, *, code: str, status: int = 409) -> None:
        super().__init__(message)
        self.code = str(code)
        self.status = int(status)


class ProviderCallBudgetExceeded(RuntimeError):
    """A persisted execution run has no provider-call reservations remaining."""

    code = "provider_call_budget_exhausted"

    def __init__(self, run_id: str, max_calls: int) -> None:
        self.run_id = str(run_id or "")
        self.max_calls = int(max_calls)
        super().__init__(
            f"provider call budget exhausted for run {self.run_id} "
            f"(max_calls={self.max_calls})"
        )


class ProviderCallKindBudgetExceeded(RuntimeError):
    """One sealed provider-call kind has no reservations remaining."""

    code = "provider_call_kind_budget_exhausted"

    def __init__(self, run_id: str, kind: str, max_calls: int) -> None:
        self.run_id = str(run_id or "")
        self.kind = str(kind or "")
        self.max_calls = int(max_calls)
        super().__init__(
            f"provider call kind budget exhausted for run {self.run_id} "
            f"(kind={self.kind}, max_calls={self.max_calls})"
        )


class RoundExecutionTraceConflict(ValueError):
    """A round trace cannot be projected completely and safely."""


_INITIALIZATION_EPOCH_MS: ContextVar[int | None] = ContextVar(
    "studio_store_initialization_epoch_ms",
    default=None,
)
_INITIALIZATION_ID_COUNTER: ContextVar[int | None] = ContextVar(
    "studio_store_initialization_id_counter",
    default=None,
)
_STARTUP_FILE_SUFFIXES = {
    "main": "",
    "wal": "-wal",
    "shm": "-shm",
    "journal": "-journal",
}


def now_ms() -> int:
    initialization_epoch_ms = _INITIALIZATION_EPOCH_MS.get()
    if initialization_epoch_ms is not None:
        return initialization_epoch_ms
    return int(time.time() * 1000)


def new_id(prefix: str) -> str:
    prefix_text = str(prefix)
    initialization_epoch_ms = _INITIALIZATION_EPOCH_MS.get()
    if initialization_epoch_ms is None:
        return f"{prefix_text}_{uuid.uuid4().hex[:12]}"
    counter = _INITIALIZATION_ID_COUNTER.get()
    if counter is None:
        raise RuntimeError("Deterministic initialization ID counter is not active")
    canonical_payload = json.dumps(
        {
            "counter": counter,
            "epoch_ms": initialization_epoch_ms,
            "prefix": prefix_text,
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    suffix = hashlib.sha256(canonical_payload).hexdigest()[:12]
    _INITIALIZATION_ID_COUNTER.set(counter + 1)
    return f"{prefix_text}_{suffix}"


def normalize_idle_response_mode(value: Any, *, fallback: str = "stored_only") -> str:
    mode = str(value or "").strip().lower()
    return mode if mode in IDLE_RESPONSE_MODES else fallback


def _is_system_temporary_database(path: Path) -> bool:
    system_temp = Path(tempfile.gettempdir()).expanduser().resolve()
    return path.is_relative_to(system_temp)


def _is_isolated_temporary_database(path: Path) -> bool:
    skip_local_env = os.getenv("AI_STUDIO_SKIP_LOCAL_ENV", "").strip() == "1"
    return skip_local_env and _is_system_temporary_database(path)


def _require_unaliased_initialization_target(
    path: Path,
    *,
    must_exist: bool,
) -> None:
    if not path.exists():
        if must_exist:
            raise RuntimeError("Migration shadow database must already exist")
        return
    if not path.is_file():
        raise RuntimeError("Schema initialization target must be a regular file")
    try:
        link_count = int(path.stat().st_nlink)
    except OSError as exc:
        raise RuntimeError("Cannot inspect schema initialization target identity") from exc
    if link_count != 1:
        raise RuntimeError(
            "Schema initialization refuses hard-linked database targets"
        )


def _validate_migration_epoch_ms(migration_epoch_ms: int | None) -> None:
    if (
        migration_epoch_ms is not None
        and (
            isinstance(migration_epoch_ms, bool)
            or not isinstance(migration_epoch_ms, int)
            or migration_epoch_ms < 0
        )
    ):
        raise ValueError("migration_epoch_ms must be a non-negative integer or None")


def _run_schema_initialization(
    store: StudioStore,
    migration_epoch_ms: int | None,
) -> None:
    _validate_migration_epoch_ms(migration_epoch_ms)
    epoch_token = _INITIALIZATION_EPOCH_MS.set(migration_epoch_ms)
    counter_token = _INITIALIZATION_ID_COUNTER.set(
        0 if migration_epoch_ms is not None else None
    )
    try:
        store._initialize()
    finally:
        _INITIALIZATION_ID_COUNTER.reset(counter_token)
        _INITIALIZATION_EPOCH_MS.reset(epoch_token)


def _file_identity(path: Path) -> dict[str, Any]:
    lexists = os.path.lexists(os.fspath(path))
    if not lexists:
        return {"exists": False, "size": 0, "sha256": ""}
    if path.is_symlink():
        raise RuntimeError(
            f"Startup database component may not be a symlink: {path}"
        )
    try:
        before = path.stat()
    except FileNotFoundError:
        raise RuntimeError(
            f"Startup database component disappeared or is a dangling link: {path}"
        )
    except OSError as exc:
        raise RuntimeError(f"Cannot inspect startup database file: {path}") from exc
    reparse_flag = int(getattr(statlib, "FILE_ATTRIBUTE_REPARSE_POINT", 0) or 0)
    if bool(
        reparse_flag and int(getattr(before, "st_file_attributes", 0) or 0) & reparse_flag
    ):
        raise RuntimeError(
            f"Startup database component may not be a reparse point: {path}"
        )
    if not path.is_file():
        raise RuntimeError(f"Startup database component is not a regular file: {path}")
    if int(getattr(before, "st_nlink", 1)) != 1:
        raise RuntimeError(
            f"Startup database component refuses a hard-linked file: {path}"
        )
    digest = hashlib.sha256()
    try:
        with path.open("rb") as source:
            for chunk in iter(lambda: source.read(1024 * 1024), b""):
                digest.update(chunk)
        after = path.stat()
    except OSError as exc:
        raise RuntimeError(f"Cannot hash startup database file: {path}") from exc
    before_state = (
        before.st_dev,
        before.st_ino,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    )
    after_state = (
        after.st_dev,
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    )
    if before_state != after_state:
        raise RuntimeError(f"Startup database component changed while hashing: {path}")
    return {
        "exists": True,
        "size": int(after.st_size),
        "sha256": digest.hexdigest(),
    }


def _startup_identity(path: Path) -> dict[str, dict[str, Any]]:
    return {
        name: _file_identity(Path(f"{path}{suffix}"))
        for name, suffix in _STARTUP_FILE_SUFFIXES.items()
    }


def _normalize_startup_identity(value: Any) -> dict[str, dict[str, Any]]:
    if not isinstance(value, Mapping):
        raise RuntimeError("Verified startup identity must be a file identity mapping")
    normalized: dict[str, dict[str, Any]] = {}
    for name in _STARTUP_FILE_SUFFIXES:
        component = value.get(name)
        if not isinstance(component, Mapping):
            raise RuntimeError(
                f"Verified startup identity is missing the {name} component"
            )
        exists = component.get("exists")
        size = component.get("size")
        sha256 = str(component.get("sha256") or "").strip().lower()
        if not isinstance(exists, bool):
            raise RuntimeError(
                f"Verified startup {name} existence flag must be boolean"
            )
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise RuntimeError(
                f"Verified startup {name} size must be a non-negative integer"
            )
        if exists:
            if not re.fullmatch(r"[0-9a-f]{64}", sha256):
                raise RuntimeError(
                    f"Verified startup {name} digest must be a SHA-256 value"
                )
        elif size != 0 or sha256:
            raise RuntimeError(
                f"Absent verified startup {name} must have zero size and no digest"
            )
        normalized[name] = {
            "exists": exists,
            "size": size,
            "sha256": sha256,
        }
    if normalized["main"]["exists"] is not True:
        raise RuntimeError("Verified startup main database must exist")
    present_sidecars = [
        name
        for name in ("wal", "shm", "journal")
        if normalized[name]["exists"]
    ]
    if present_sidecars:
        raise RuntimeError(
            "Verified startup refuses SQLite sidecars: "
            + ", ".join(present_sidecars)
        )
    return normalized


def _startup_identities_match(
    expected: Mapping[str, Mapping[str, Any]],
    actual: Mapping[str, Mapping[str, Any]],
) -> bool:
    for name in _STARTUP_FILE_SUFFIXES:
        expected_component = expected[name]
        actual_component = actual[name]
        if (
            expected_component["exists"] is not actual_component["exists"]
            or expected_component["size"] != actual_component["size"]
            or not hmac.compare_digest(
                str(expected_component["sha256"]),
                str(actual_component["sha256"]),
            )
        ):
            return False
    return True


def _initialize_migration_shadow(
    path: Path,
    migration_epoch_ms: int,
) -> StudioStore:
    """Initialize a deterministic migration shadow under the system temp root.

    This internal entry point deliberately does not depend on the isolated-test
    environment flag.  Its path boundary is the authority: it can never create
    or migrate a database outside the resolved system temporary directory.
    """

    requested_path = Path(path).expanduser()
    offending_component = first_reparse_component(requested_path)
    if offending_component is not None:
        raise RuntimeError(
            "Migration shadow path may not contain a symlink or reparse point: "
            f"{offending_component}"
        )
    clean_path = requested_path.resolve()
    if not _is_system_temporary_database(clean_path):
        raise RuntimeError(
            "Migration shadows may initialize schemas only under the system temp "
            "directory."
        )
    _require_unaliased_initialization_target(clean_path, must_exist=True)
    if migration_epoch_ms is None:
        raise ValueError("migration_epoch_ms is required for migration shadows")
    _validate_migration_epoch_ms(migration_epoch_ms)
    instance = StudioStore.__new__(StudioStore)
    instance.path = clean_path
    instance._lock = threading.RLock()
    _run_schema_initialization(instance, migration_epoch_ms)
    return instance


class StudioStore:
    def __init__(
        self,
        path: Path = DATABASE_PATH,
        *,
        migration_epoch_ms: int | None = None,
    ) -> None:
        requested_path = Path(path).expanduser()
        offending_component = first_reparse_component(requested_path)
        if offending_component is not None:
            raise RuntimeError(
                "StudioStore path may not contain a symlink or reparse point: "
                f"{offending_component}"
            )
        self.path = requested_path.resolve()
        self._lock = threading.RLock()
        if not _is_isolated_temporary_database(self.path):
            raise RuntimeError(
                "StudioStore may initialize schemas only for isolated tests with "
                "AI_STUDIO_SKIP_LOCAL_ENV=1 and a database under the system temp directory."
            )
        _require_unaliased_initialization_target(self.path, must_exist=False)
        _run_schema_initialization(self, migration_epoch_ms)

    @classmethod
    def _open_existing_schema(cls, path: Path) -> StudioStore:
        """Construct a store handle without creating, seeding, or migrating schema."""

        requested_path = Path(path).expanduser()
        offending_component = first_reparse_component(requested_path)
        if offending_component is not None:
            raise RuntimeError(
                "Startup-verified path may not contain a symlink or reparse point: "
                f"{offending_component}"
            )
        clean_path = requested_path.resolve()
        if not clean_path.is_file():
            raise RuntimeError(f"Startup-verified database does not exist: {clean_path}")
        instance = cls.__new__(cls)
        instance.path = clean_path
        instance._lock = threading.RLock()
        return instance

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.path, timeout=20)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA journal_mode=WAL")
        connection.execute("PRAGMA foreign_keys=ON")
        return connection

    def _initialize(self) -> None:
        with self._lock, closing(self._connect()) as connection, connection:
            connection.executescript(
                """
                CREATE TABLE IF NOT EXISTS rooms (
                    id TEXT PRIMARY KEY,
                    title TEXT NOT NULL,
                    objective TEXT NOT NULL DEFAULT '',
                    domain TEXT NOT NULL DEFAULT 'open_collaboration',
                    category TEXT NOT NULL DEFAULT '通用共创',
                    template_id TEXT NOT NULL DEFAULT 'open_collaboration',
                    capability_packs_json TEXT NOT NULL DEFAULT '[]',
                    plugin_registry_snapshot_json TEXT NOT NULL DEFAULT '{}',
                    plugin_lifecycle_resolution_json TEXT NOT NULL DEFAULT '{}',
                    plugin_lifecycle_resolution_sha256 TEXT NOT NULL DEFAULT '',
                    discussion_mode TEXT NOT NULL DEFAULT 'dynamic',
                    moderator_member_id TEXT NOT NULL DEFAULT '',
                    idle_response_mode TEXT NOT NULL DEFAULT 'mention_only',
                    workflow_policy_json TEXT NOT NULL DEFAULT '{}',
                    stock_room_scope_json TEXT NOT NULL DEFAULT '{}',
                    stock_room_scope_sha256 TEXT NOT NULL DEFAULT '',
                    settings_version INTEGER NOT NULL DEFAULT 1,
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL
                );
                CREATE TABLE IF NOT EXISTS room_versions (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    snapshot_json TEXT NOT NULL,
                    snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    changed_at INTEGER NOT NULL,
                    UNIQUE(room_id, version),
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS members (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    name TEXT NOT NULL,
                    identity TEXT NOT NULL DEFAULT '',
                    instructions TEXT NOT NULL DEFAULT '',
                    responsibilities TEXT NOT NULL DEFAULT '',
                    boundaries TEXT NOT NULL DEFAULT '',
                    stance TEXT NOT NULL DEFAULT 'neutral',
                    workflow_stage TEXT NOT NULL DEFAULT 'flexible',
                    capabilities_json TEXT NOT NULL DEFAULT '[]',
                    provider TEXT NOT NULL DEFAULT 'openai',
                    model TEXT NOT NULL DEFAULT '',
                    position INTEGER NOT NULL DEFAULT 0,
                    enabled INTEGER NOT NULL DEFAULT 1,
                    avatar_color TEXT NOT NULL DEFAULT '#2563eb',
                    archived_at INTEGER NOT NULL DEFAULT 0,
                    archived_enabled INTEGER NOT NULL DEFAULT 0,
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL DEFAULT 0,
                    version INTEGER NOT NULL DEFAULT 1,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS member_versions (
                    id TEXT PRIMARY KEY,
                    member_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    snapshot_json TEXT NOT NULL,
                    snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    changed_at INTEGER NOT NULL,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS rounds (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    objective TEXT NOT NULL DEFAULT '',
                    status TEXT NOT NULL DEFAULT 'RUNNING',
                    created_at INTEGER NOT NULL,
                    completed_at INTEGER NOT NULL DEFAULT 0,
                    updated_at INTEGER NOT NULL DEFAULT 0,
                    resume_count INTEGER NOT NULL DEFAULT 0,
                    pause_requested INTEGER NOT NULL DEFAULT 0,
                    pause_requested_at INTEGER NOT NULL DEFAULT 0,
                    turn_contract_version TEXT,
                    candidate_risk_review_version TEXT,
                    turn_envelope_version TEXT,
                    turn_envelope_schema_sha256 TEXT,
                    plugin_registry_snapshot_json TEXT NOT NULL DEFAULT '{}',
                    plugin_registry_snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    plugin_lifecycle_resolution_json TEXT NOT NULL DEFAULT '{}',
                    plugin_lifecycle_resolution_sha256 TEXT NOT NULL DEFAULT '',
                    turn_ledger_sha256 TEXT NOT NULL DEFAULT '',
                    execution_audit_version TEXT,
                    trace_anchor_head_sequence INTEGER NOT NULL DEFAULT 0
                        CHECK(trace_anchor_head_sequence >= 0),
                    trace_anchor_head_sha256 TEXT NOT NULL DEFAULT '',
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS round_checkpoints (
                    round_id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    step_number INTEGER NOT NULL DEFAULT 0,
                    state_json TEXT NOT NULL,
                    state_sha256 TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    FOREIGN KEY(round_id) REFERENCES rounds(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS director_decisions (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL,
                    sequence_no INTEGER NOT NULL CHECK(sequence_no > 0),
                    action TEXT NOT NULL CHECK(action IN ('speak', 'finish')),
                    member_id TEXT NOT NULL DEFAULT '',
                    member_name TEXT NOT NULL DEFAULT '',
                    reason TEXT NOT NULL DEFAULT '',
                    source TEXT NOT NULL DEFAULT '',
                    stage TEXT NOT NULL DEFAULT '',
                    workspace_focus_json TEXT NOT NULL DEFAULT '{}',
                    moderator_context_json TEXT NOT NULL DEFAULT '{}',
                    decision_sha256 TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    UNIQUE(round_id, sequence_no),
                    FOREIGN KEY(round_id) REFERENCES rounds(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS director_attempts (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL,
                    sequence_no INTEGER NOT NULL CHECK(sequence_no > 0),
                    moderator_member_id TEXT NOT NULL,
                    moderator_member_version INTEGER NOT NULL
                        CHECK(moderator_member_version > 0),
                    provider TEXT NOT NULL,
                    model TEXT NOT NULL DEFAULT '',
                    status TEXT NOT NULL
                        CHECK(status IN ('STARTED','RESPONDED','FAILED','INVALID','CANCELLED')),
                    error_code TEXT NOT NULL DEFAULT '',
                    response_summary_sha256 TEXT NOT NULL DEFAULT '',
                    decision_summary_sha256 TEXT NOT NULL DEFAULT '',
                    selected_member_id TEXT NOT NULL DEFAULT '',
                    director_decision_id TEXT NOT NULL DEFAULT '',
                    turn_order INTEGER NOT NULL DEFAULT 0 CHECK(turn_order >= 0),
                    attempt_token_sha256 TEXT NOT NULL UNIQUE,
                    started_at INTEGER NOT NULL,
                    finished_at INTEGER NOT NULL DEFAULT 0,
                    UNIQUE(round_id, sequence_no),
                    CHECK(
                        (status='STARTED' AND finished_at=0)
                        OR (status<>'STARTED' AND finished_at>0)
                    ),
                    FOREIGN KEY(round_id) REFERENCES rounds(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS round_turns (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL,
                    turn_order INTEGER NOT NULL CHECK(turn_order > 0),
                    member_id TEXT NOT NULL,
                    member_version INTEGER NOT NULL DEFAULT 1,
                    member_snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    director_decision_id TEXT NOT NULL DEFAULT '',
                    status TEXT NOT NULL DEFAULT 'STARTED'
                        CHECK(status IN ('STARTED','RESPONDED','FAILED')),
                    message_id TEXT NOT NULL DEFAULT '',
                    checkpoint_state_json TEXT NOT NULL DEFAULT '{}',
                    checkpoint_state_sha256 TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    UNIQUE(round_id, turn_order),
                    FOREIGN KEY(round_id) REFERENCES rounds(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS messages (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL DEFAULT '',
                    sender_type TEXT NOT NULL,
                    sender_id TEXT NOT NULL DEFAULT '',
                    sender_name TEXT NOT NULL,
                    identity TEXT NOT NULL DEFAULT '',
                    provider TEXT NOT NULL DEFAULT '',
                    model TEXT NOT NULL DEFAULT '',
                    content TEXT NOT NULL,
                    reply_to TEXT NOT NULL DEFAULT '',
                    reply_to_message_id TEXT NOT NULL DEFAULT '',
                    client_message_id TEXT NOT NULL DEFAULT '',
                    routing_fingerprint TEXT NOT NULL DEFAULT '',
                    round_turn_id TEXT NOT NULL DEFAULT '',
                    turn_contract_version TEXT,
                    turn_contract_json TEXT,
                    turn_contract_sha256 TEXT,
                    turn_contract_qualified INTEGER
                        CHECK(turn_contract_qualified IS NULL OR turn_contract_qualified IN (0,1)),
                    turn_contract_issues_json TEXT,
                    member_version INTEGER NOT NULL DEFAULT 0,
                    created_at INTEGER NOT NULL,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS message_mentions (
                    message_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    member_id TEXT NOT NULL,
                    member_version INTEGER NOT NULL,
                    sequence_no INTEGER NOT NULL CHECK(sequence_no >= 0),
                    created_at INTEGER NOT NULL,
                    PRIMARY KEY(message_id, member_id),
                    UNIQUE(message_id, sequence_no),
                    FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,
                    FOREIGN KEY(member_id) REFERENCES members(id)
                );
                CREATE TABLE IF NOT EXISTS chat_requests (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    source_message_id TEXT NOT NULL UNIQUE,
                    round_id TEXT NOT NULL DEFAULT '',
                    kind TEXT NOT NULL CHECK(kind IN ('idle_mention','round_interjection')),
                    target_mode TEXT NOT NULL CHECK(target_mode IN ('explicit','moderated')),
                    request_mode TEXT NOT NULL DEFAULT 'mention_only',
                    skip_providers_json TEXT NOT NULL DEFAULT '[]',
                    status TEXT NOT NULL DEFAULT 'PENDING'
                        CHECK(status IN ('PENDING','PROCESSING','COMPLETED','PARTIAL','FAILED','CANCELLED')),
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,
                    FOREIGN KEY(source_message_id) REFERENCES messages(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS chat_request_targets (
                    request_id TEXT NOT NULL,
                    member_id TEXT NOT NULL,
                    member_version INTEGER NOT NULL,
                    sequence_no INTEGER NOT NULL CHECK(sequence_no >= 0),
                    status TEXT NOT NULL DEFAULT 'PENDING'
                        CHECK(status IN ('PENDING','PROCESSING','RESPONDED','FAILED','CANCELLED')),
                    response_message_id TEXT NOT NULL DEFAULT '',
                    error_code TEXT NOT NULL DEFAULT '',
                    claim_token TEXT NOT NULL DEFAULT '',
                    lease_owner TEXT NOT NULL DEFAULT '',
                    lease_until INTEGER NOT NULL DEFAULT 0,
                    attempt_count INTEGER NOT NULL DEFAULT 0,
                    updated_at INTEGER NOT NULL,
                    PRIMARY KEY(request_id, member_id),
                    UNIQUE(request_id, sequence_no),
                    FOREIGN KEY(request_id) REFERENCES chat_requests(id) ON DELETE CASCADE,
                    FOREIGN KEY(member_id) REFERENCES members(id)
                );
                CREATE TABLE IF NOT EXISTS chat_request_attempts (
                    id TEXT PRIMARY KEY,
                    request_id TEXT NOT NULL,
                    member_id TEXT NOT NULL,
                    attempt_no INTEGER NOT NULL CHECK(attempt_no > 0),
                    claim_token TEXT NOT NULL UNIQUE,
                    lease_owner TEXT NOT NULL DEFAULT '',
                    status TEXT NOT NULL CHECK(status IN ('STARTED','RESPONDED','FAILED','CANCELLED','ABANDONED')),
                    error_code TEXT NOT NULL DEFAULT '',
                    started_at INTEGER NOT NULL,
                    finished_at INTEGER NOT NULL DEFAULT 0,
                    UNIQUE(request_id, member_id, attempt_no),
                    FOREIGN KEY(request_id) REFERENCES chat_requests(id) ON DELETE CASCADE,
                    FOREIGN KEY(member_id) REFERENCES members(id)
                );
                CREATE TABLE IF NOT EXISTS materials (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    kind TEXT NOT NULL DEFAULT 'note',
                    source_url TEXT NOT NULL DEFAULT '',
                    content TEXT NOT NULL DEFAULT '',
                    version INTEGER NOT NULL DEFAULT 1,
                    active INTEGER NOT NULL DEFAULT 1,
                    official_supplement_pending INTEGER NOT NULL DEFAULT 0
                        CHECK(official_supplement_pending IN (0,1)),
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS material_versions (
                    id TEXT PRIMARY KEY,
                    material_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    snapshot_json TEXT NOT NULL,
                    changed_at INTEGER NOT NULL,
                    FOREIGN KEY(material_id) REFERENCES materials(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS material_official_attestations (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    material_id TEXT NOT NULL,
                    material_version INTEGER NOT NULL CHECK(material_version > 0),
                    evidence_kind TEXT NOT NULL CHECK(evidence_kind='earnings_material'),
                    symbol TEXT NOT NULL,
                    fiscal_period TEXT NOT NULL,
                    material_kind TEXT NOT NULL,
                    official_url TEXT NOT NULL,
                    candidate_sha256 TEXT NOT NULL,
                    candidate_snapshot_json TEXT NOT NULL DEFAULT '{}',
                    original_error_codes_json TEXT NOT NULL DEFAULT '[]',
                    source_sha256 TEXT NOT NULL,
                    content_sha256 TEXT NOT NULL,
                    material_snapshot_sha256 TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'STAGED'
                        CHECK(status IN ('STAGED','CONFIRMED')),
                    staged_at INTEGER NOT NULL,
                    confirmed_by TEXT NOT NULL DEFAULT '',
                    confirmed_at INTEGER NOT NULL DEFAULT 0,
                    UNIQUE(room_id,material_id,material_version,official_url),
                    FOREIGN KEY(material_id) REFERENCES materials(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS message_citations (
                    message_id TEXT NOT NULL,
                    material_id TEXT NOT NULL,
                    material_version INTEGER NOT NULL,
                    created_at INTEGER NOT NULL,
                    PRIMARY KEY(message_id, material_id),
                    FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE,
                    FOREIGN KEY(material_id) REFERENCES materials(id)
                );
                CREATE TABLE IF NOT EXISTS manual_chatgpt_sessions (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL UNIQUE,
                    mode TEXT NOT NULL CHECK(mode IN ('quick','standard','deep')),
                    state TEXT NOT NULL CHECK(state IN (
                        'DRAFT','BUNDLE_READY','WAITING_FOR_CHATGPT',
                        'RESULT_IMPORTED','VALIDATING','API_REVIEW',
                        'READY_FOR_DECISION','FROZEN','CONTEXT_STALE',
                        'IMPORT_REJECTED','BUDGET_BLOCKED','NEEDS_USER_ACTION'
                    )),
                    objective TEXT NOT NULL,
                    bundle_json TEXT NOT NULL,
                    bundle_sha256 TEXT NOT NULL CHECK(length(bundle_sha256)=64),
                    context_sha256 TEXT NOT NULL CHECK(length(context_sha256)=64),
                    result_json TEXT NOT NULL DEFAULT '{}',
                    result_sha256 TEXT NOT NULL DEFAULT ''
                        CHECK(length(result_sha256) IN (0,64)),
                    declared_model TEXT NOT NULL DEFAULT '',
                    declared_model_trusted INTEGER NOT NULL DEFAULT 0
                        CHECK(declared_model_trusted=0),
                    last_issues_json TEXT NOT NULL DEFAULT '[]',
                    event_sequence INTEGER NOT NULL DEFAULT 0
                        CHECK(event_sequence >= 0),
                    event_head_sha256 TEXT NOT NULL DEFAULT ''
                        CHECK(length(event_head_sha256) IN (0,64)),
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    frozen_at INTEGER NOT NULL DEFAULT 0,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS manual_chatgpt_events (
                    id TEXT PRIMARY KEY,
                    session_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    sequence_no INTEGER NOT NULL CHECK(sequence_no > 0),
                    from_state TEXT NOT NULL,
                    to_state TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    payload_json TEXT NOT NULL,
                    previous_event_sha256 TEXT NOT NULL DEFAULT ''
                        CHECK(length(previous_event_sha256) IN (0,64)),
                    event_sha256 TEXT NOT NULL CHECK(length(event_sha256)=64),
                    created_at INTEGER NOT NULL,
                    UNIQUE(session_id,sequence_no),
                    FOREIGN KEY(session_id) REFERENCES manual_chatgpt_sessions(id)
                        ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS manual_chatgpt_review_runs (
                    id TEXT PRIMARY KEY,
                    session_id TEXT NOT NULL UNIQUE,
                    room_id TEXT NOT NULL,
                    provider_execution_run_id TEXT NOT NULL UNIQUE,
                    client_request_id TEXT NOT NULL,
                    provider TEXT NOT NULL,
                    requested_model TEXT NOT NULL DEFAULT '',
                    mode TEXT NOT NULL CHECK(mode IN ('quick','standard','deep')),
                    status TEXT NOT NULL CHECK(status IN (
                        'RUNNING','COMPLETED','FAILED','BUDGET_BLOCKED'
                    )),
                    expected_calls INTEGER NOT NULL CHECK(expected_calls BETWEEN 2 AND 4),
                    completed_calls INTEGER NOT NULL DEFAULT 0
                        CHECK(completed_calls BETWEEN 0 AND expected_calls),
                    plan_json TEXT NOT NULL,
                    plan_sha256 TEXT NOT NULL CHECK(length(plan_sha256)=64),
                    error_code TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    completed_at INTEGER NOT NULL DEFAULT 0,
                    UNIQUE(session_id,client_request_id),
                    FOREIGN KEY(session_id) REFERENCES manual_chatgpt_sessions(id)
                        ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,
                    FOREIGN KEY(provider_execution_run_id) REFERENCES provider_execution_runs(id)
                );
                CREATE TABLE IF NOT EXISTS manual_chatgpt_api_reviews (
                    id TEXT PRIMARY KEY,
                    review_run_id TEXT NOT NULL,
                    session_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    review_index INTEGER NOT NULL CHECK(review_index BETWEEN 1 AND 4),
                    review_kind TEXT NOT NULL CHECK(review_kind IN (
                        'fact_check','counterargument','risk_review','evidence_audit'
                    )),
                    provider TEXT NOT NULL,
                    requested_model TEXT NOT NULL DEFAULT '',
                    response_model TEXT NOT NULL DEFAULT '',
                    independence_classification TEXT NOT NULL CHECK(
                        independence_classification IN (
                            'same_model_independent_call',
                            'different_provider_independent_opinion'
                        )
                    ),
                    provider_attempt_id TEXT NOT NULL UNIQUE,
                    request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),
                    review_json TEXT NOT NULL,
                    review_sha256 TEXT NOT NULL CHECK(length(review_sha256)=64),
                    created_at INTEGER NOT NULL,
                    UNIQUE(review_run_id,review_index),
                    UNIQUE(session_id,review_kind),
                    FOREIGN KEY(review_run_id) REFERENCES manual_chatgpt_review_runs(id)
                        ON DELETE CASCADE,
                    FOREIGN KEY(session_id) REFERENCES manual_chatgpt_sessions(id)
                        ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,
                    FOREIGN KEY(provider_attempt_id) REFERENCES provider_call_attempts(id)
                );
                CREATE TABLE IF NOT EXISTS manual_chatgpt_decisions (
                    session_id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    review_run_id TEXT NOT NULL UNIQUE,
                    result_sha256 TEXT NOT NULL CHECK(length(result_sha256)=64),
                    reviews_sha256 TEXT NOT NULL CHECK(length(reviews_sha256)=64),
                    decision_card_json TEXT NOT NULL,
                    decision_card_sha256 TEXT NOT NULL UNIQUE
                        CHECK(length(decision_card_sha256)=64),
                    selected_option_id TEXT NOT NULL DEFAULT '',
                    confirmation_json TEXT NOT NULL DEFAULT '{}',
                    confirmation_sha256 TEXT NOT NULL DEFAULT ''
                        CHECK(length(confirmation_sha256) IN (0,64)),
                    created_at INTEGER NOT NULL,
                    frozen_at INTEGER NOT NULL DEFAULT 0,
                    FOREIGN KEY(session_id) REFERENCES manual_chatgpt_sessions(id)
                        ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE,
                    FOREIGN KEY(review_run_id) REFERENCES manual_chatgpt_review_runs(id)
                );
                CREATE TABLE IF NOT EXISTS manual_chatgpt_review_recoveries (
                    id TEXT PRIMARY KEY,
                    record_version TEXT NOT NULL
                        CHECK(record_version='manual_chatgpt_review_recovery_v1'),
                    session_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    previous_review_run_id TEXT NOT NULL UNIQUE,
                    previous_provider_execution_run_id TEXT NOT NULL,
                    previous_run_snapshot_json TEXT NOT NULL,
                    previous_run_snapshot_sha256 TEXT NOT NULL
                        CHECK(length(previous_run_snapshot_sha256)=64),
                    acknowledgement TEXT NOT NULL CHECK(
                        acknowledgement='REAUTHORIZE_ORPHANED_ZERO_CALL_REVIEW'
                    ),
                    created_at INTEGER NOT NULL,
                    FOREIGN KEY(session_id) REFERENCES manual_chatgpt_sessions(id)
                        ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS project_invocation_intakes (
                    id TEXT PRIMARY KEY,
                    record_version TEXT NOT NULL
                        CHECK(record_version='project_invocation_intake_v1'),
                    envelope_version TEXT NOT NULL
                        CHECK(envelope_version='project_invocation_envelope_v1'),
                    caller_id TEXT NOT NULL CHECK(length(caller_id) BETWEEN 1 AND 80),
                    project_id TEXT NOT NULL CHECK(length(project_id) BETWEEN 1 AND 160),
                    client_request_id TEXT NOT NULL
                        CHECK(length(client_request_id) BETWEEN 1 AND 160),
                    request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64),
                    source_item_id TEXT NOT NULL DEFAULT '',
                    source_revision TEXT NOT NULL DEFAULT '',
                    result_profile TEXT NOT NULL CHECK(
                        result_profile IN (
                            'decision_v1','research_report_v1','artifact_draft_v1'
                        )
                    ),
                    request_semantics_json TEXT NOT NULL,
                    request_semantics_sha256 TEXT NOT NULL
                        CHECK(length(request_semantics_sha256)=64),
                    retention_policy TEXT NOT NULL CHECK(
                        retention_policy IN (
                            'project_default','no_payload_retention',
                            'ephemeral_24h','bounded_days'
                        )
                    ),
                    payload_retention_allowed INTEGER NOT NULL
                        CHECK(payload_retention_allowed IN (0,1)),
                    room_payload_persisted INTEGER NOT NULL
                        CHECK(room_payload_persisted IN (0,1)),
                    retention_expires_at INTEGER NOT NULL DEFAULT 0
                        CHECK(retention_expires_at >= 0),
                    room_id TEXT NOT NULL UNIQUE,
                    room_settings_version INTEGER NOT NULL
                        CHECK(room_settings_version > 0),
                    room_snapshot_sha256 TEXT NOT NULL
                        CHECK(length(room_snapshot_sha256)=64),
                    creation_authorization_sha256 TEXT NOT NULL
                        CHECK(length(creation_authorization_sha256)=64),
                    creation_capability_jti_sha256 TEXT NOT NULL
                        CHECK(length(creation_capability_jti_sha256)=64),
                    creation_capability_expires_at INTEGER NOT NULL
                        CHECK(creation_capability_expires_at > 0),
                    created_at INTEGER NOT NULL,
                    UNIQUE(caller_id,project_id,client_request_id),
                    FOREIGN KEY(room_id,room_settings_version)
                        REFERENCES room_versions(room_id,version) ON DELETE RESTRICT
                );
                CREATE TABLE IF NOT EXISTS artifacts (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL DEFAULT '',
                    kind TEXT NOT NULL DEFAULT 'meeting_minutes',
                    generation_key TEXT NOT NULL DEFAULT '',
                    title TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'DRAFT',
                    version INTEGER NOT NULL DEFAULT 1,
                    content_json TEXT NOT NULL,
                    plugin_registry_snapshot_json TEXT NOT NULL DEFAULT '{}',
                    plugin_registry_snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    plugin_registry_source_type TEXT NOT NULL DEFAULT '',
                    plugin_registry_source_id TEXT NOT NULL DEFAULT '',
                    plugin_lifecycle_resolution_json TEXT NOT NULL DEFAULT '{}',
                    plugin_lifecycle_resolution_sha256 TEXT NOT NULL DEFAULT '',
                    generation_source TEXT NOT NULL DEFAULT 'manual',
                    created_by TEXT NOT NULL DEFAULT 'system',
                    confirmed_by TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    confirmed_at INTEGER NOT NULL DEFAULT 0,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS artifact_versions (
                    id TEXT PRIMARY KEY,
                    artifact_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    snapshot_json TEXT NOT NULL,
                    snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    changed_at INTEGER NOT NULL,
                    FOREIGN KEY(artifact_id) REFERENCES artifacts(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS artifact_evidence (
                    artifact_id TEXT NOT NULL,
                    item_key TEXT NOT NULL,
                    source_type TEXT NOT NULL,
                    source_id TEXT NOT NULL,
                    source_version INTEGER NOT NULL DEFAULT 0,
                    source_revision TEXT NOT NULL DEFAULT '',
                    source_snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    evidence_role TEXT NOT NULL DEFAULT 'context',
                    verification_status TEXT NOT NULL DEFAULT 'unreviewed',
                    review_note TEXT NOT NULL DEFAULT '',
                    version_decision TEXT NOT NULL DEFAULT 'current',
                    created_at INTEGER NOT NULL,
                    PRIMARY KEY(artifact_id,item_key,source_type,source_id),
                    FOREIGN KEY(artifact_id) REFERENCES artifacts(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS artifact_evidence_review_events (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    artifact_id TEXT NOT NULL,
                    artifact_version INTEGER NOT NULL CHECK(artifact_version > 0),
                    sequence_no INTEGER NOT NULL CHECK(sequence_no > 0),
                    event_version TEXT NOT NULL,
                    event_type TEXT NOT NULL
                        CHECK(event_type IN ('created','revised','confirmed')),
                    artifact_status TEXT NOT NULL
                        CHECK(artifact_status IN ('DRAFT','CONFIRMED')),
                    relation_snapshot_json TEXT NOT NULL,
                    relation_snapshot_sha256 TEXT NOT NULL
                        CHECK(length(relation_snapshot_sha256) = 64),
                    previous_event_sha256 TEXT NOT NULL DEFAULT ''
                        CHECK(length(previous_event_sha256) IN (0,64)),
                    event_sha256 TEXT NOT NULL UNIQUE CHECK(length(event_sha256) = 64),
                    created_by TEXT NOT NULL DEFAULT 'user',
                    created_at INTEGER NOT NULL,
                    UNIQUE(artifact_id,artifact_version),
                    UNIQUE(artifact_id,sequence_no),
                    FOREIGN KEY(artifact_id) REFERENCES artifacts(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS artifact_evidence_review_heads (
                    artifact_id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    chain_version TEXT NOT NULL,
                    head_sequence INTEGER NOT NULL CHECK(head_sequence > 0),
                    head_sha256 TEXT NOT NULL CHECK(length(head_sha256) = 64),
                    event_count INTEGER NOT NULL CHECK(event_count = head_sequence),
                    history_start_artifact_version INTEGER NOT NULL
                        CHECK(history_start_artifact_version > 0),
                    updated_at INTEGER NOT NULL,
                    FOREIGN KEY(artifact_id) REFERENCES artifacts(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS artifact_user_decisions (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    artifact_id TEXT NOT NULL,
                    artifact_version INTEGER NOT NULL CHECK(artifact_version > 0),
                    action TEXT NOT NULL CHECK(action IN ('support', 'hold', 'return')),
                    rationale TEXT NOT NULL,
                    preferred_option_id TEXT NOT NULL DEFAULT '',
                    decision_version TEXT NOT NULL DEFAULT 'artifact_user_decision_v1',
                    ai_preferred_option_id TEXT NOT NULL DEFAULT '',
                    selected_option_id TEXT NOT NULL DEFAULT '',
                    selected_option_revision INTEGER NOT NULL DEFAULT 0,
                    selected_option_origin_message_id TEXT NOT NULL DEFAULT '',
                    selected_option_latest_message_id TEXT NOT NULL DEFAULT '',
                    selected_option_snapshot_sha256 TEXT NOT NULL DEFAULT '',
                    selected_option_risk_review_required INTEGER NOT NULL DEFAULT 0,
                    decision_record_sha256 TEXT NOT NULL DEFAULT '',
                    artifact_snapshot_sha256 TEXT NOT NULL,
                    governance_attestation_sha256 TEXT,
                    created_by TEXT NOT NULL DEFAULT 'user',
                    created_at INTEGER NOT NULL,
                    FOREIGN KEY(artifact_id) REFERENCES artifacts(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS artifact_governance_attestations (
                    artifact_id TEXT NOT NULL,
                    artifact_version INTEGER NOT NULL CHECK(artifact_version > 0),
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL,
                    attestation_version TEXT NOT NULL,
                    evaluator_version TEXT NOT NULL,
                    round_governance_input_sha256 TEXT NOT NULL,
                    projection_json TEXT NOT NULL,
                    projection_sha256 TEXT NOT NULL,
                    artifact_binding_sha256 TEXT NOT NULL,
                    attestation_json TEXT NOT NULL,
                    attestation_sha256 TEXT NOT NULL,
                    created_at INTEGER NOT NULL,
                    PRIMARY KEY(artifact_id, artifact_version),
                    FOREIGN KEY(artifact_id) REFERENCES artifacts(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS decision_lineage_events (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    user_decision_id TEXT NOT NULL,
                    sequence_no INTEGER NOT NULL CHECK(sequence_no > 0),
                    relation_type TEXT NOT NULL CHECK(
                        relation_type IN (
                            'implements', 'revises', 'confirms', 'tests',
                            'evaluates', 'records_outcome'
                        )
                    ),
                    resource_type TEXT NOT NULL,
                    resource_id TEXT NOT NULL,
                    resource_revision TEXT NOT NULL DEFAULT '',
                    resource_state TEXT NOT NULL DEFAULT '',
                    relation_note TEXT NOT NULL DEFAULT '',
                    resource_snapshot_json TEXT NOT NULL,
                    resource_snapshot_sha256 TEXT NOT NULL CHECK(length(resource_snapshot_sha256) = 64),
                    previous_event_sha256 TEXT NOT NULL DEFAULT '',
                    event_sha256 TEXT NOT NULL CHECK(length(event_sha256) = 64),
                    created_by TEXT NOT NULL DEFAULT 'user',
                    created_at INTEGER NOT NULL,
                    UNIQUE(user_decision_id, sequence_no),
                    UNIQUE(
                        user_decision_id, relation_type, resource_type,
                        resource_id, resource_revision, resource_snapshot_sha256
                    ),
                    FOREIGN KEY(user_decision_id) REFERENCES artifact_user_decisions(id) ON DELETE RESTRICT,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS observations (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    round_id TEXT NOT NULL DEFAULT '',
                    artifact_id TEXT NOT NULL DEFAULT '',
                    artifact_version INTEGER NOT NULL DEFAULT 0,
                    member_version INTEGER NOT NULL DEFAULT 0,
                    methodology_id TEXT NOT NULL DEFAULT 'directional_threshold',
                    methodology_version INTEGER NOT NULL DEFAULT 1,
                    confidence_source TEXT NOT NULL DEFAULT 'unverified',
                    sample_key TEXT NOT NULL DEFAULT '',
                    symbol TEXT NOT NULL,
                    direction TEXT NOT NULL,
                    horizon_days INTEGER NOT NULL,
                    threshold_pct REAL NOT NULL DEFAULT 0,
                    thesis TEXT NOT NULL,
                    counter_case TEXT NOT NULL DEFAULT '',
                    model_confidence REAL,
                    evidence_json TEXT NOT NULL DEFAULT '{}',
                    created_by TEXT NOT NULL DEFAULT 'user',
                    status TEXT NOT NULL DEFAULT 'PROPOSED',
                    user_confirmed INTEGER NOT NULL DEFAULT 0,
                    baseline_price REAL,
                    baseline_time TEXT NOT NULL DEFAULT '',
                    baseline_snapshot_id TEXT NOT NULL DEFAULT '',
                    measurement_method TEXT NOT NULL DEFAULT 'snapshot_last_to_qfq_close_v1',
                    scoring_baseline_price REAL,
                    scoring_baseline_time TEXT NOT NULL DEFAULT '',
                    benchmark_baseline_json TEXT NOT NULL DEFAULT '{}',
                    outcome_price REAL,
                    outcome_time TEXT NOT NULL DEFAULT '',
                    return_pct REAL,
                    hit INTEGER,
                    benchmark_result_json TEXT NOT NULL DEFAULT '{}',
                    relative_return_pct REAL,
                    relative_hit INTEGER,
                    resolution_note TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    confirmed_at INTEGER NOT NULL DEFAULT 0,
                    resolved_at INTEGER NOT NULL DEFAULT 0,
                    updated_at INTEGER NOT NULL,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS observation_reflections (
                    id TEXT PRIMARY KEY,
                    observation_id TEXT NOT NULL UNIQUE,
                    room_id TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'DRAFT',
                    version INTEGER NOT NULL DEFAULT 1,
                    source_snapshot_json TEXT NOT NULL,
                    source_snapshot_hash TEXT NOT NULL,
                    lesson TEXT NOT NULL DEFAULT '',
                    caveat TEXT NOT NULL DEFAULT '',
                    next_test TEXT NOT NULL DEFAULT '',
                    created_by TEXT NOT NULL DEFAULT 'system',
                    confirmed_by TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    confirmed_at INTEGER NOT NULL DEFAULT 0,
                    FOREIGN KEY(observation_id) REFERENCES observations(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS observation_reflection_versions (
                    id TEXT PRIMARY KEY,
                    reflection_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    snapshot_json TEXT NOT NULL,
                    changed_at INTEGER NOT NULL,
                    FOREIGN KEY(reflection_id) REFERENCES observation_reflections(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS paper_portfolios (
                    id TEXT PRIMARY KEY,
                    room_id TEXT NOT NULL,
                    name TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'DRAFT',
                    version INTEGER NOT NULL DEFAULT 1,
                    positions_json TEXT NOT NULL,
                    budgets_json TEXT NOT NULL,
                    stress_scenarios_json TEXT NOT NULL,
                    evaluation_json TEXT NOT NULL,
                    candidate_simulation_contract_json TEXT NOT NULL DEFAULT '{}',
                    candidate_simulation_contract_sha256 TEXT NOT NULL DEFAULT '',
                    created_by TEXT NOT NULL DEFAULT 'user',
                    confirmed_by TEXT NOT NULL DEFAULT '',
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    confirmed_at INTEGER NOT NULL DEFAULT 0,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS paper_portfolio_versions (
                    id TEXT PRIMARY KEY,
                    portfolio_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    version INTEGER NOT NULL,
                    snapshot_json TEXT NOT NULL,
                    changed_at INTEGER NOT NULL,
                    FOREIGN KEY(portfolio_id) REFERENCES paper_portfolios(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS paper_portfolio_walk_forward_runs (
                    id TEXT PRIMARY KEY,
                    portfolio_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    portfolio_version INTEGER NOT NULL,
                    record_version INTEGER NOT NULL DEFAULT 1,
                    engine_version TEXT NOT NULL,
                    result_version TEXT NOT NULL,
                    portfolio_snapshot_sha256 TEXT NOT NULL,
                    input_hash TEXT NOT NULL,
                    input_snapshot_sha256 TEXT NOT NULL,
                    input_snapshot_json TEXT NOT NULL,
                    result_sha256 TEXT NOT NULL,
                    candidate_simulation_contract_sha256 TEXT NOT NULL DEFAULT '',
                    candidate_evaluation_basis_sha256 TEXT NOT NULL DEFAULT '',
                    integrity_profile_json TEXT NOT NULL DEFAULT '{}',
                    integrity_profile_sha256 TEXT NOT NULL DEFAULT '',
                    config_json TEXT NOT NULL,
                    result_json TEXT NOT NULL,
                    created_by TEXT NOT NULL DEFAULT 'user',
                    created_at INTEGER NOT NULL,
                    FOREIGN KEY(portfolio_id) REFERENCES paper_portfolios(id) ON DELETE CASCADE,
                    FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
                );
                CREATE TABLE IF NOT EXISTS schema_migrations (
                    key TEXT PRIMARY KEY,
                    applied_at INTEGER NOT NULL
                );
                CREATE INDEX IF NOT EXISTS idx_members_room_position ON members(room_id, position);
                CREATE INDEX IF NOT EXISTS idx_room_versions_room ON room_versions(room_id, version DESC);
                CREATE INDEX IF NOT EXISTS idx_messages_room_time ON messages(room_id, created_at);
                CREATE INDEX IF NOT EXISTS idx_messages_room_keyset
                    ON messages(room_id, created_at DESC, id DESC);
                CREATE INDEX IF NOT EXISTS idx_rounds_room_time ON rounds(room_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_round_checkpoints_room_time ON round_checkpoints(room_id, updated_at DESC);
                CREATE INDEX IF NOT EXISTS idx_director_decisions_room_time
                    ON director_decisions(room_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_director_decisions_room_round_time
                    ON director_decisions(room_id, round_id, created_at, id);
                CREATE INDEX IF NOT EXISTS idx_director_attempts_room_time
                    ON director_attempts(room_id, started_at DESC);
                CREATE INDEX IF NOT EXISTS idx_director_attempts_room_round_sequence
                    ON director_attempts(room_id, round_id, sequence_no);
                CREATE UNIQUE INDEX IF NOT EXISTS uq_director_attempts_round_started
                    ON director_attempts(round_id) WHERE status='STARTED';
                CREATE INDEX IF NOT EXISTS idx_round_turns_room_round
                    ON round_turns(room_id, round_id, turn_order);
                CREATE INDEX IF NOT EXISTS idx_member_versions_member ON member_versions(member_id, version DESC);
                CREATE INDEX IF NOT EXISTS idx_materials_room_time ON materials(room_id, updated_at DESC);
                CREATE INDEX IF NOT EXISTS idx_material_versions_material ON material_versions(material_id, version DESC);
                CREATE INDEX IF NOT EXISTS idx_material_official_attestations_room
                    ON material_official_attestations(room_id, confirmed_at DESC);
                CREATE INDEX IF NOT EXISTS idx_artifacts_room_time ON artifacts(room_id, updated_at DESC);
                CREATE INDEX IF NOT EXISTS idx_artifact_versions_artifact ON artifact_versions(artifact_id, version DESC);
                CREATE INDEX IF NOT EXISTS idx_manual_chatgpt_sessions_room
                    ON manual_chatgpt_sessions(room_id,created_at DESC,id DESC);
                CREATE INDEX IF NOT EXISTS idx_manual_chatgpt_events_session
                    ON manual_chatgpt_events(session_id,sequence_no);
                CREATE INDEX IF NOT EXISTS idx_manual_chatgpt_review_runs_room
                    ON manual_chatgpt_review_runs(room_id,created_at DESC,id DESC);
                CREATE INDEX IF NOT EXISTS idx_manual_chatgpt_api_reviews_session
                    ON manual_chatgpt_api_reviews(session_id,review_index);
                CREATE INDEX IF NOT EXISTS idx_manual_chatgpt_review_recoveries_session
                    ON manual_chatgpt_review_recoveries(session_id,created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_project_invocation_project_time
                    ON project_invocation_intakes(
                        caller_id,project_id,created_at DESC,id DESC
                    );
                CREATE INDEX IF NOT EXISTS idx_project_invocation_source_item
                    ON project_invocation_intakes(
                        caller_id,project_id,source_item_id,source_revision
                    ) WHERE source_item_id<>'';
                CREATE UNIQUE INDEX IF NOT EXISTS uq_artifact_versions_entity_version
                    ON artifact_versions(artifact_id, version);
                CREATE INDEX IF NOT EXISTS idx_artifact_evidence_artifact ON artifact_evidence(artifact_id, item_key);
                CREATE INDEX IF NOT EXISTS idx_artifact_evidence_review_events_artifact
                    ON artifact_evidence_review_events(room_id, artifact_id, sequence_no);
                CREATE INDEX IF NOT EXISTS idx_artifact_user_decisions_artifact
                    ON artifact_user_decisions(artifact_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_artifact_governance_room_round
                    ON artifact_governance_attestations(room_id, round_id, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_decision_lineage_room_decision
                    ON decision_lineage_events(room_id, user_decision_id, sequence_no);
                CREATE INDEX IF NOT EXISTS idx_decision_lineage_resource
                    ON decision_lineage_events(room_id, resource_type, resource_id, sequence_no);
                CREATE INDEX IF NOT EXISTS idx_observations_room_status ON observations(room_id, status, created_at DESC);
                CREATE INDEX IF NOT EXISTS idx_observations_symbol_horizon ON observations(symbol, horizon_days, status);
                CREATE INDEX IF NOT EXISTS idx_reflections_room_status ON observation_reflections(room_id, status, updated_at DESC);
                CREATE INDEX IF NOT EXISTS idx_reflection_versions_reflection ON observation_reflection_versions(reflection_id, version DESC);
                CREATE INDEX IF NOT EXISTS idx_paper_portfolios_room_time ON paper_portfolios(room_id, updated_at DESC);
                CREATE INDEX IF NOT EXISTS idx_paper_portfolio_versions ON paper_portfolio_versions(portfolio_id, version DESC);
                CREATE UNIQUE INDEX IF NOT EXISTS uq_paper_portfolio_versions_entity_version
                    ON paper_portfolio_versions(portfolio_id, version);
                CREATE INDEX IF NOT EXISTS idx_paper_walk_forward_runs
                    ON paper_portfolio_walk_forward_runs(room_id, portfolio_id, created_at DESC);
                """
            )
            schema_applied_at_ms = now_ms()
            ensure_source_inbox_schema(connection)
