    @staticmethod
    def _rebuild_decision_lineage_events_table(
        connection: sqlite3.Connection,
        *,
        temporary_table: str,
        allowed_relations: tuple[str, ...],
    ) -> None:
        if temporary_table not in {
            "decision_lineage_events_v2",
            "decision_lineage_events_v3",
        }:
            raise ValueError("决策谱系迁移临时表无效")
        relation_sql = ", ".join(f"'{item}'" for item in allowed_relations)
        temporary_row = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
            (temporary_table,),
        ).fetchone()
        if temporary_row:
            main_rows = connection.execute(
                "SELECT id,event_sha256 FROM decision_lineage_events ORDER BY id"
            ).fetchall()
            temporary_rows = connection.execute(
                f"SELECT id,event_sha256 FROM {temporary_table} ORDER BY id"
            ).fetchall()
            main_fingerprints = [tuple(row) for row in main_rows]
            temporary_fingerprints = [tuple(row) for row in temporary_rows]
            if not main_fingerprints and temporary_fingerprints:
                connection.execute("DROP TABLE decision_lineage_events")
                connection.execute(
                    f"ALTER TABLE {temporary_table} RENAME TO decision_lineage_events"
                )
                connection.execute(
                    "CREATE INDEX IF NOT EXISTS idx_decision_lineage_room_decision "
                    "ON decision_lineage_events(room_id, user_decision_id, sequence_no)"
                )
                connection.execute(
                    "CREATE INDEX IF NOT EXISTS idx_decision_lineage_resource "
                    "ON decision_lineage_events(room_id, resource_type, resource_id, sequence_no)"
                )
                return
            if temporary_fingerprints and temporary_fingerprints != main_fingerprints:
                raise RuntimeError("检测到不完整且内容冲突的决策谱系迁移，拒绝覆盖")
            connection.execute(f"DROP TABLE {temporary_table}")

        connection.execute(
            f"""CREATE TABLE {temporary_table} (
                id TEXT PRIMARY KEY,
                room_id TEXT NOT NULL,
                user_decision_id TEXT NOT NULL,
                sequence_no INTEGER NOT NULL CHECK(sequence_no > 0),
                relation_type TEXT NOT NULL CHECK(relation_type IN ({relation_sql})),
                resource_type TEXT NOT NULL,
                resource_id TEXT NOT NULL,
                resource_revision TEXT NOT NULL DEFAULT '',
                resource_state TEXT NOT NULL DEFAULT '',
                relation_note TEXT NOT NULL DEFAULT '',
                resource_snapshot_json TEXT NOT NULL,
                resource_snapshot_sha256 TEXT NOT NULL CHECK(length(resource_snapshot_sha256) = 64),
                previous_event_sha256 TEXT NOT NULL DEFAULT '',
                event_sha256 TEXT NOT NULL CHECK(length(event_sha256) = 64),
                created_by TEXT NOT NULL DEFAULT 'user',
                created_at INTEGER NOT NULL,
                UNIQUE(user_decision_id, sequence_no),
                UNIQUE(
                    user_decision_id, relation_type, resource_type,
                    resource_id, resource_revision, resource_snapshot_sha256
                ),
                FOREIGN KEY(user_decision_id) REFERENCES artifact_user_decisions(id) ON DELETE RESTRICT,
                FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE CASCADE
            )"""
        )
        connection.execute(
            f"""INSERT INTO {temporary_table}(
                id,room_id,user_decision_id,sequence_no,relation_type,
                resource_type,resource_id,resource_revision,resource_state,
                relation_note,resource_snapshot_json,resource_snapshot_sha256,
                previous_event_sha256,event_sha256,created_by,created_at
            )
            SELECT
                id,room_id,user_decision_id,sequence_no,relation_type,
                resource_type,resource_id,resource_revision,resource_state,
                relation_note,resource_snapshot_json,resource_snapshot_sha256,
                previous_event_sha256,event_sha256,created_by,created_at
            FROM decision_lineage_events"""
        )
        connection.execute("DROP TABLE decision_lineage_events")
        connection.execute(
            f"ALTER TABLE {temporary_table} RENAME TO decision_lineage_events"
        )
        connection.execute(
            "CREATE INDEX idx_decision_lineage_room_decision "
            "ON decision_lineage_events(room_id, user_decision_id, sequence_no)"
        )
        connection.execute(
            "CREATE INDEX idx_decision_lineage_resource "
            "ON decision_lineage_events(room_id, resource_type, resource_id, sequence_no)"
        )

    def _apply_decision_lineage_validation_relation_migration(
        self,
        connection: sqlite3.Connection,
    ) -> None:
        migration_key = "decision_lineage_validation_relations_v2"
        if connection.execute(
            "SELECT 1 FROM schema_migrations WHERE key=?",
            (migration_key,),
        ).fetchone():
            return
        connection.execute("SAVEPOINT decision_lineage_validation_v2")
        try:
            table_sql_row = connection.execute(
                "SELECT sql FROM sqlite_master WHERE type='table' AND name='decision_lineage_events'"
            ).fetchone()
            table_sql = str(table_sql_row["sql"] or "") if table_sql_row else ""
            temporary_exists = connection.execute(
                """SELECT 1 FROM sqlite_master
                   WHERE type='table' AND name='decision_lineage_events_v2'"""
            ).fetchone()
            if (
                "'tests'" not in table_sql
                or "'evaluates'" not in table_sql
                or temporary_exists
            ):
                self._rebuild_decision_lineage_events_table(
                    connection,
                    temporary_table="decision_lineage_events_v2",
                    allowed_relations=(
                        "implements",
                        "revises",
                        "confirms",
                        "tests",
                        "evaluates",
                    ),
                )
            connection.execute(
                "INSERT INTO schema_migrations(key,applied_at) VALUES(?,?)",
                (migration_key, now_ms()),
            )
        except Exception:
            connection.execute("ROLLBACK TO SAVEPOINT decision_lineage_validation_v2")
            connection.execute("RELEASE SAVEPOINT decision_lineage_validation_v2")
            raise
        connection.execute("RELEASE SAVEPOINT decision_lineage_validation_v2")

